function typeOf(file){const t=(file.mimeType||'').toLowerCase(),e=(file.name.split('.').pop()||'').toLowerCase();if(t.startsWith('image/')||['png','jpg','jpeg','gif','webp','svg','heic'].includes(e))return'image';if(t.startsWith('video/')||['mp4','mov','mkv','webm'].includes(e))return'video';if(t.startsWith('audio/')||['mp3','wav','m4a','ogg'].includes(e))return'audio';if(e==='pdf'||t.includes('pdf'))return'pdf';if(['zip','rar','7z','gz','tar'].includes(e))return'archive';if(['doc','docx','txt','md','rtf'].includes(e))return'doc';return'file'}
