function remoteRenameModal(id,oldName){openModal(`<div class="modal-head"><div><h2>Rename item</h2><p>Rename “${esc(oldName)}” in the provider.</p></div><button class="modal-close" aria-label="Close">${iconSvg('close')}</button></div><label class="field-label" for="remoteNewName">New name</label><input id="remoteNewName" class="form-input" maxlength="255" value="${esc(oldName)}"><div class="modal-actions"><button class="button" id="cancelRemoteRename">Cancel</button><button class="button primary" id="saveRemoteRename">Save name</button></div>`);$('#cancelRemoteRename').onclick=closeModal;$('#saveRemoteRename').onclick=async()=>{const name=$('#remoteNewName').value.trim();if(!name)return toast('Enter a name',false);try{const r=await fetch(`/api/providers/${activeProvider}/item?id=${encodeURIComponent(id)}&accountId=${encodeURIComponent(activeAccountId)}`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({name})}),d=await r.json();if(!r.ok)throw new Error(d.error||'Could not rename item.');closeModal();toast('Renamed');renderProviderFiles()}catch(e){toast(e.message,false)}}}
