 $('#providerDone').onclick=closeModal;$$('[data-refresh-quota]').forEach(b=>b.onclick=()=>refreshQuotaTotals(b));$('#addGoogleAccountModal')?.addEventListener('click',async()=>{closeModal();await startGoogleConnect()});$$('[data-open-connection]').forEach(b=>b.onclick=()=>{closeModal();goProvider('google',b.dataset.openConnection)});$$('[data-provider-action]').forEach(b=>b.onclick=async()=>{closeModal();await providerAction(b.dataset.providerAction)})
