function confirmModal(title,body,label,action){openModal(`<div class="modal-head"><div><h2>${esc(title)}</h2><p>${esc(body)}</p></div><button class="modal-close" aria-label="Close">${iconSvg('close')}</button></div><div class="modal-actions"><button class="button" id="cancelModal">Cancel</button><button class="button primary" id="confirmAction">${esc(label)}</button></div>`);$('#cancelModal').onclick=closeModal;$('#confirmAction').onclick=action}
function shareModal(file){const token=file.shareToken||uid().replaceAll('-',''),url=`${location.origin}${location.pathname}#share/${token}`;if(!file.shareToken){file.shareToken=token;file.updatedAt=Date.now();persist()}openModal(`<div class="modal-head"><div><h2>Share “${esc(file.name)}”</h2><p>Anyone with this link can access this file in this browser.</p></div><button class="modal-close" aria-label="Close">${iconSvg('close')}</button></div><label class="field-label">Share link</label><div class="share-link-row"><input id="shareUrl" class="form-input" readonly value="${esc(url)}"><button class="button primary" id="copyShare">Copy</button></div><label class="field-label">Link settings</label><label class="share-expiry"><input id="shareDownload" type="checkbox" checked> Allow downloading this file</label><div class="form-help">Links are local to this browser and are not publicly reachable. Password protection and expiration are available with the hosted provider release.</div><div class="modal-actions"><button class="button" id="revokeShare">Revoke link</button><button class="button" id="closeShare">Done</button></div>`);$('#closeShare').onclick=closeModal;$('#copyShare').onclick=async()=>{try{await navigator.clipboard.writeText(url)}catch{ $('#shareUrl').select();document.execCommand('copy')}toast('Share link copied')};$('#revokeShare').onclick=()=>{file.shareToken=null;persist();closeModal();render();toast('Share link revoked')};$('#shareDownload').onchange=e=>{file.shareDownload=e.target.checked;persist()}}
function previewModal(file){blobGet(file.id).then(blob=>{if(!blob)return toast('File data is unavailable in this browser',false);const url=URL.createObjectURL(blob),type=typeOf(file),preview=type==='image'?`<img src="${url}" style="max-width:100%;max-height:60vh;border-radius:8px">`:type==='video'?`<video src="${url}" controls style="max-width:100%;max-height:60vh"></video>`:type==='audio'?`<audio src="${url}" controls></audio>`:type==='pdf'?`<iframe src="${url}" style="width:100%;height:55vh;border:0"></iframe>`:`<div class="notice-box">Preview isn't available for this file type. You can download it to open it on your device.</div>`;openModal(`<div class="modal-head"><div><h2>${esc(file.name)}</h2><p>${bytes(file.size)} · ${esc(file.mimeType||'File')}</p></div><button class="modal-close" aria-label="Close">${iconSvg('close')}</button></div><div style="display:grid;place-items:center;min-height:130px">${preview}</div><div class="modal-actions"><button class="button" id="previewDownload">Download</button><button class="button primary" id="previewClose">Done</button></div>`);$('#previewClose').onclick=()=>{URL.revokeObjectURL(url);closeModal()};$('#previewDownload').onclick=()=>downloadFile(file)})}
function attachFileActions(){ $$('[data-menu]').forEach(b=>b.onclick=e=>{e.stopPropagation();menuId=menuId===b.dataset.menu?null:b.dataset.menu;render()});$$('[data-action]').forEach(b=>b.onclick=e=>{e.stopPropagation();const f=state.files.find(x=>x.id===b.dataset.id);if(!f)return;menuId=null;const action=b.dataset.action;if(action==='open')openItem(f.id);if(action==='rename')folderModal(f);if(action==='star'){f.starred=!f.starred;f.updatedAt=Date.now();persist();render();toast(f.starred?'Added to starred':'Removed from starred')}if(action==='trash'){f.deleted=true;f.updatedAt=Date.now();persist();render();toast('Moved to trash')}if(action==='restore'){f.deleted=false;f.updatedAt=Date.now();persist();render();toast('Restored')}if(action==='purge')confirmModal('Delete forever?','This permanently removes the file and its local browser data.','Delete forever',async()=>{await blobDelete(f.id);state.files=state.files.filter(x=>x.id!==f.id);state.folders=state.folders.filter(x=>x.id!==f.id);persist();closeModal();render();toast('File permanently deleted')});if(action==='download')downloadFile(f);if(action==='share')shareModal(f)});$$('.file-row[data-row]').forEach(el=>el.onclick=e=>{if(e.target.closest('button')||e.target.closest('.menu-popover'))return;openItem(el.dataset.row)});document.addEventListener('click',()=>{if(menuId){menuId=null;render() }},{once:true}) }
function openItem(id){const f=state.files.find(x=>x.id===id);if(!f)return;if(f.kind==='folder'){currentFolder=f.id;currentPage='files';render()}else previewModal(f)}
async function downloadFile(file){const blob=await blobGet(file.id);if(!blob)return toast('File data is unavailable in this browser',false);const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);toast('Download started')}
let uploadDestination={kind:'local'};
function uploadDestinationModal(){const accounts=(providerInfo('google').accounts||[]).map(a=>`<button class="provider-option" data-upload-direct="google" data-account="${esc(a.id)}"><span class="storage-provider-icon gdrive">G</span><span class="provider-option-copy"><b>Google Drive</b><small>${esc(a.email||a.label)}</small></span><span class="provider-pill">Direct</span></button>`).join(''),s3=providerInfo('s3');openModal(`<div class="modal-head"><div><h2>Where should this upload go?</h2><p>Choose local storage or let NDrive select a cloud destination.</p></div><button class="modal-close" aria-label="Close">${iconSvg('close')}</button></div><div class="provider-options"><button class="provider-option" data-upload-local><span class="storage-provider-icon">${iconSvg('home')}</span><span class="provider-option-copy"><b>This device</b><small>Keep it in this browser profile</small></span><span class="provider-pill">Local</span></button><button class="provider-option" data-upload-auto><span class="storage-provider-icon s3">${iconSvg('arrowRight')}</span><span class="provider-option-copy"><b>Automatic cloud routing</b><small>${esc(state.policy==='round-robin'?'Round robin':state.policy==='priority'?'Priority order':'Most available')} across connected storage</small></span><span class="provider-pill">Smart</span></button>${accounts}${s3.connected?'<button class="provider-option" data-upload-direct="s3"><span class="storage-provider-icon s3">S3</span><span class="provider-option-copy"><b>S3 compatible</b><small>Upload directly to this bucket</small></span><span class="provider-pill">Direct</span></button>':''}</div><div class="modal-actions"><button class="button" id="uploadCancel">Cancel</button></div>`);$('#uploadCancel').onclick=closeModal;$$('[data-upload-local]').forEach(b=>b.onclick=()=>{uploadDestination={kind:'local'};closeModal();$('#fileInput').click()});$$('[data-upload-auto]').forEach(b=>b.onclick=()=>{uploadDestination={kind:'auto'};closeModal();$('#fileInput').click()});$$('[data-upload-direct]').forEach(b=>b.onclick=()=>{uploadDestination={kind:'direct',provider:b.dataset.uploadDirect,accountId:b.dataset.account||''};closeModal();$('#fileInput').click()})}
function uploadProgress(file){let root=$('#uploadProgressRoot');if(!root){document.body.insertAdjacentHTML('beforeend','<aside id="uploadProgressRoot" class="upload-progress-panel" aria-live="polite"></aside>');root=$('#uploadProgressRoot')}const id=uid();root.insertAdjacentHTML('beforeend',`<div class="upload-progress-item" id="${id}"><div class="upload-progress-head"><span>${esc(file.name)}</span><small>Waiting</small></div><div class="progress-bar"><span></span></div></div>`);return{root,item:document.getElementById(id),id}}
function uploadWithProgress(url,file,headers,progress){return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST',url);xhr.withCredentials=true;for(const [k,v] of Object.entries(headers))xhr.setRequestHeader(k,v);xhr.upload.onprogress=e=>{if(e.lengthComputable){const percent=Math.round(e.loaded/e.total*100);progress.item.querySelector('small').textContent=`${percent}%`;progress.item.querySelector('.progress-bar span').style.width=`${percent}%`}};xhr.onload=()=>{let data={};try{data=JSON.parse(xhr.responseText)}catch{}if(xhr.status<200||xhr.status>=300){reject(new Error(data.error||`Upload failed (${xhr.status})`));return}progress.item.querySelector('small').textContent='Complete';progress.item.classList.add('complete');resolve(data)};xhr.onerror=()=>reject(new Error('Network error during upload.'));xhr.onabort=()=>reject(new Error('Upload was cancelled.'));xhr.send(file)})}
async function addFiles(fileList){const files=[...fileList];if(!files.length)return;if(currentPage==='provider'&&uploadDestination.kind==='local')uploadDestination={kind:'direct',provider:activeProvider,accountId:activeAccountId,parentId:remoteParentId};if(uploadDestination.kind!=='local'){const destination={...uploadDestination,parentId:currentPage==='provider'?remoteParentId:''};let uploaded=0,lastResult;for(const file of files){const progress=uploadProgress(file);try{progress.item.querySelector('small').textContent='0%';let url,headers={'Content-Type':file.type||'application/octet-stream','X-File-Name':encodeURIComponent(file.name)};if(destination.kind==='auto'){url='/api/storage/upload';headers['X-NDrive-Provider']='auto'}else{const q=new URLSearchParams({name:file.name,mimeType:file.type||'application/octet-stream',size:String(file.size),...(destination.accountId?{accountId:destination.accountId}:{}),...(destination.parentId?{parentId:destination.parentId}:{})});url=`/api/providers/${destination.provider}/files?${q}`}lastResult=await uploadWithProgress(url,file,headers,progress);uploaded++}catch(e){progress.item.classList.add('failed');progress.item.querySelector('small').textContent='Failed';progress.item.title=e.message;toast(`${file.name}: ${e.message}`,false)}finally{setTimeout(()=>progress.item?.remove(),6500)}}if(uploaded){await refreshProviderStatus();toast(`${uploaded} ${uploaded===1?'file':'files'} uploaded to cloud storage`);if(destination.kind==='direct'&&currentPage==='provider')await renderProviderFiles();else if(destination.kind==='auto'&&lastResult){const p=lastResult.provider,account=lastResult.accountId;if(p==='google')goProvider(p,account);else goProvider(p)}}uploadDestination={kind:'local'};return}let added=0;for(const f of files){const id=uid();try{await blobPut(id,f);state.files.push({id,name:f.name,kind:'file',mimeType:f.type,size:f.size,folderId:currentFolder,updatedAt:Date.now(),createdAt:Date.now(),starred:false});added++}catch{toast(`Couldn't save ${f.name} in this browser`,false)}}persist();render();toast(`${added} ${added===1?'file':'files'} uploaded to this device`)}
$('#fileInput').addEventListener('change',e=>{addFiles(e.target.files);e.target.value=''});
window.addEventListener('dragover',e=>{e.preventDefault();$('.drop-overlay')?.classList.add('show')});window.addEventListener('dragleave',e=>{if(e.clientX<=0||e.clientY<=0||e.clientX>=innerWidth||e.clientY>=innerHeight) $('.drop-overlay')?.classList.remove('show')});window.addEventListener('drop',e=>{e.preventDefault();$('.drop-overlay')?.classList.remove('show');addFiles(e.dataTransfer.files)});document.body.insertAdjacentHTML('beforeend','<div class="drop-overlay">Drop your files to add them to NDrive</div>');
$('#searchInput').addEventListener('input',()=>{if(currentPage==='cloud')renderCloudFiles();else if(currentPage==='provider')renderProviderFiles();else{if(currentPage!=='files')currentPage='files';currentFolder='root';render()}});$('#helpButton').onclick=()=>helpModal();function helpModal(){openModal(`<div class="modal-head"><div><h2>A little help getting started</h2><p>Your files, one calmer place.</p></div><button class="modal-close" aria-label="Close">${iconSvg('close')}</button></div><div class="help-steps"><div class="help-step"><span class="step-number">1</span><div><b>Add your files</b><p>Choose a destination in the upload dialog: This device or one connected cloud account. Dragging a file opens the same destination choices.</p></div></div><div class="help-step"><span class="step-number">2</span><div><b>Make it yours</b><p>Create folders, star important items, and search by file name. Use the ··· menu for more actions.</p></div></div><div class="help-step"><span class="step-number">3</span><div><b>Keep a copy</b><p>Download important files to your computer. Browser data can be cleared by your device or browser settings.</p></div></div></div><div class="notice-box"><strong>Cloud connections:</strong> Google sign-in only signs you in to NDrive. To browse a Drive, choose Storage, choose Add Google Drive and approve the separate Drive access request. Local files stay in this browser.</div><div class="modal-actions"><a class="button" href="README.md" target="_blank">Open user guide</a><button class="button primary" id="helpDone">Got it</button></div>`);$('#helpDone').onclick=closeModal}
$('#mobileMenu').onclick=()=>{const s=$('#sidebar');s.classList.toggle('open');if(s.classList.contains('open')){document.querySelector('.mobile-overlay')?.remove();document.body.insertAdjacentHTML('beforeend','<div class="mobile-overlay"></div>');$('.mobile-overlay').onclick=()=>{s.classList.remove('open');$('.mobile-overlay')?.remove()}}else $('.mobile-overlay')?.remove()};$('#addStorage').onclick=providerModal;$('#connectStorage').onclick=providerModal;$('#workspaceSwitch').onclick=()=>toast('Personal workspace');document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#searchInput').focus()}if(e.key==='Escape')closeModal()});
function renderShareRoute(){const token=decodeURIComponent(location.hash.split('/')[1]||''),f=state.files.find(x=>x.shareToken===token&&!x.deleted);if(!f){$('#pageContent').innerHTML=`<div class="empty-state"><div class="empty-illustration">${iconSvg('share')}</div><h3>This share link isn't available</h3><p>It may have been revoked, or this link was created on another browser.</p><button class="button primary" id="backHome">Go to NDrive</button></div>`;$('#backHome').onclick=()=>go('files');return true}$('#pageContent').innerHTML=`<div class="empty-state" style="margin:8vh auto;background:#fff;border:1px solid var(--line);border-radius:14px;max-width:520px"><div class="empty-illustration">${fileIcon(f)}</div><div class="eyebrow">SHARED WITH YOU</div><h3>${esc(f.name)}</h3><p>${bytes(f.size)} · Shared from this device's NDrive workspace</p><button class="button primary" id="sharedDownload">${iconSvg('download')} Download file</button><p style="margin-top:14px;font-size:9px">Local share links only work in the browser where the file was saved.</p></div>`;$('#sharedDownload').onclick=()=>downloadFile(f);return true}
function authScreen(setupRequired,allowSignups=false,register=false,googleLoginAvailable=false){
 document.body.classList.add('auth-required');$('.auth-screen')?.remove();const showCreate=setupRequired||register,authError=new URLSearchParams(location.search).get('auth_error')||'';
 document.body.insertAdjacentHTML('beforeend',`<main class="auth-screen"><section class="auth-card"><div class="auth-brand"><span class="brand-mark"><svg viewBox="0 0 32 32" aria-hidden="true"><path d="M6 22.7 13.5 8l4.3 8.2L21 10l5 12.7"/><path d="M6 22.7h20"/><circle cx="23" cy="7" r="2"/></svg></span><span class="brand-name">n<span>drive</span></span></div><div class="auth-copy"><div class="eyebrow">PRIVATE FILE STORAGE</div><h1>${setupRequired?'Set up your NDrive account':register?'Create your account':'Welcome back'}</h1><p>${setupRequired?'Create the owner account to secure this NDrive server.':register?'Create an account for this NDrive server.':'Sign in to access your files and connected storage.'}</p></div>${googleLoginAvailable?`<button class="auth-google-button" id="authGoogle" type="button"><span class="auth-google-mark" aria-hidden="true">G</span><span>Continue with Google</span></button><p class="auth-google-note">Use a verified Google email to sign in. Drive storage is connected separately.</p><div class="auth-divider"><span>or use email</span></div>`:''}<form id="authForm">${showCreate?'<label class="field-label" for="authName">Your name</label><input id="authName" class="form-input" autocomplete="name" required maxlength="80" placeholder="Name">':''}<label class="field-label" for="authEmail">Email address</label><input id="authEmail" class="form-input" type="email" autocomplete="username" required placeholder="you@example.com"><label class="field-label" for="authPassword">Password</label><input id="authPassword" class="form-input" type="password" autocomplete="${showCreate?'new-password':'current-password'}" minlength="12" required placeholder="${showCreate?'At least 12 characters':'Your password'}">${showCreate?'<div class="form-help">Use at least 12 characters. NDrive stores a one-way password hash.</div>':''}<div id="authError" class="auth-error" role="alert">${esc(authError)}</div><button class="button primary auth-submit" type="submit">${setupRequired?'Create owner account':register?'Create account':'Sign in'}</button></form>${!showCreate&&allowSignups?'<p class="auth-switch">New here? <button id="showRegister" type="button">Create an account</button></p>':!showCreate?'<p class="auth-signup-closed">New account registration is turned off on this server.</p>':''}${register?'<p class="auth-switch">Already have an account? <button id="showLogin" type="button">Sign in</button></p>':''}<div class="auth-foot"><span>${iconSvg('lock')}</span> Private to this NDrive server</div></section></main>`);
 if(authError)history.replaceState({},'',location.pathname+location.hash);
 $('#authForm').onsubmit=async e=>{e.preventDefault();const submit=$('.auth-submit'),error=$('#authError');submit.disabled=true;submit.textContent=showCreate?'Creating account…':'Signing in…';error.textContent='';try{const body={email:$('#authEmail').value,password:$('#authPassword').value,...(showCreate?{name:$('#authName').value}:{})},endpoint=setupRequired?'/api/auth/setup':register?'/api/auth/register':'/api/auth/login',r=await fetch(endpoint,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)}),data=await r.json();if(!r.ok)throw new Error(data.error||'Could not sign in.');currentUser=data.user;document.body.classList.remove('auth-required');$('.auth-screen')?.remove();await initWorkspace()}catch(err){error.textContent=err.message;submit.disabled=false;submit.textContent=setupRequired?'Create owner account':register?'Create account':'Sign in'}};
 $('#authGoogle')?.addEventListener('click',async()=>{const button=$('#authGoogle'),error=$('#authError');button.disabled=true;button.querySelector('span:last-child').textContent='Connecting to Google…';error.textContent='';try{const r=await fetch('/api/auth/google',{method:'POST'}),data=await r.json();if(!r.ok)throw new Error(data.error||'Could not start Google sign-in.');location.assign(data.url)}catch(e){error.textContent=e.message;button.disabled=false;button.querySelector('span:last-child').textContent='Continue with Google'}});
 $('#showRegister')?.addEventListener('click',()=>authScreen(false,true,true,googleLoginAvailable));$('#showLogin')?.addEventListener('click',()=>authScreen(false,allowSignups,false,googleLoginAvailable))
}
async function initWorkspace(){try{DB_NAME=currentUser?.role==='admin'?'ndrive-local-v1':`ndrive-local-${currentUser?.id||'user'}`;META_KEY=currentUser?.role==='admin'?'ndrive-metadata-v1':`ndrive-metadata-${currentUser?.id||'user'}`;db=await openDB();state=JSON.parse(localStorage.getItem(META_KEY)||'null')||structuredClone(seedState);if(!Array.isArray(state.files))state=structuredClone(seedState);state.folders ||= structuredClone(seedState.folders);state.providerNames ||= ['This device'];$('.user-info b').textContent=currentUser?.name||'NDrive user';$('.user-info small').textContent=currentUser?.email||'Signed in';$('.user-avatar')?.replaceChildren(document.createTextNode((currentUser?.name||'N').slice(0,1).toUpperCase()));$('.more-button').title='Sign out';$('.more-button').onclick=async()=>{await fetch('/api/auth/logout',{method:'POST'});location.reload()};await refreshProviderStatus();if(location.hash.startsWith('#share/')){render();renderShareRoute()}else{const hash=location.hash.slice(1),page=hash.startsWith('provider-')?'provider':hash;if(page==='provider'){const parsed=parseProviderRoute(hash);activeProvider=parsed.id;activeAccountId=parsed.accountId}if(['files','cloud','starred','recent','shared','trash','settings','storage','provider'].includes(page))currentPage=page;render();const q=new URLSearchParams(location.search);if(q.get('auth')==='google-connected'){toast('Signed in with Google');history.replaceState({},'',location.pathname+location.hash)}if(q.get('google')==='connected')toast('Google Drive connected');if(q.get('google')==='error')toast(q.get('message')||'Google Drive connection failed',false)}}catch(e){console.error(e);$('#pageContent').innerHTML='<div class="empty-state"><h3>NDrive could not start</h3><p>Make sure the server is running and browser storage is enabled, then refresh this page.</p></div>'}}
async function init(){try{const r=await fetch('/api/auth/status'),status=await r.json();if(!r.ok)throw new Error(status.error||'Could not check sign-in status.');if(!status.user){authScreen(status.setupRequired,status.allowSignups,false,status.googleLoginConfigured);return}currentUser=status.user;await initWorkspace()}catch(e){console.error(e);$('#pageContent').innerHTML=`<div class="empty-state"><h3>NDrive could not start</h3><p>${esc(e.message||'Make sure the server is running, then refresh this page.')}</p></div>`}}
window.addEventListener('hashchange',()=>{if(!currentUser)return;if(location.hash.startsWith('#share/')){render();renderShareRoute()}else{const hash=location.hash.slice(1),page=hash.startsWith('provider-')?'provider':hash;if(page==='provider'){const parsed=parseProviderRoute(hash);activeProvider=parsed.id;activeAccountId=parsed.accountId;remoteParentId='';remotePath=[]}if(['files','cloud','starred','recent','shared','trash','settings','storage','provider'].includes(page)){currentPage=page;currentFolder='root';render()}}});
init();
